/**
 * Spoofball design tokens: the single source for colors, type, spacing and
 * radii. CSS reads them as custom properties generated by `cssVariables()`;
 * canvas drawing code imports them directly. See docs/design.md.
 */

export const palette = {
  /** Page background: near-black, so the court and team colors carry the screen. */
  background: '#111317',
  /** Raised surfaces: cards, panels, seat rows. */
  surface: '#1A1E24',
  /** The court's playing surface: white, like the prototype's arena. Team colors are checked against it. */
  court: '#FFFFFF',
  /** The band around the court. */
  courtRing: '#CCCCCC',
  /** Lines drawn on the court. */
  courtLine: '#D5D9E0',
  /** The mosh: the court's center scoring zone. */
  mosh: '#EEF1F5',
  /** Labels drawn on the court. */
  courtText: '#5F6670',
  text: '#E8EAED',
  textMuted: '#8A919C',
  line: '#2A2F37',
  accent: '#4A86E8',
  /** The away kit's disc. */
  white: '#FFFFFF',
  /** The ring around a selected spoof. Dark, so it reads on the white court and on any team color. */
  highlight: '#111317',
} as const;

export const teamColorNames = [
  'red',
  'orange',
  'gold',
  'green',
  'teal',
  'blue',
  'purple',
  'pink',
] as const;

export type TeamColorName = (typeof teamColorNames)[number];

export interface TeamColor {
  /** Home kit fill and away kit trim. At least 3:1 against the white court. */
  base: string;
  /** A darker shade: the home kit's trim and the away kit's mark. At least 4.5:1 against white. */
  deep: string;
}

/**
 * The prototype's 8 team colors, re-tuned for the white court: each is just
 * dark enough to stand out on white, so they have similar weight and no team
 * stands out more than another. No pure red/green.
 */
export const teamColors: Record<TeamColorName, TeamColor> = {
  red: { base: '#E5534B', deep: '#DB2920' },
  orange: { base: '#DD6E1A', deep: '#B25815' },
  gold: { base: '#A98921', deep: '#896F1B' },
  green: { base: '#449E60', deep: '#37804E' },
  teal: { base: '#2C9C97', deep: '#247E7A' },
  blue: { base: '#4A86E8', deep: '#246CE3' },
  purple: { base: '#9A6FE0', deep: '#8754DA' },
  pink: { base: '#DE61A2', deep: '#CF2B80' },
};

export const fontFamily = {
  body: 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
  numeric: 'ui-monospace, "SF Mono", "Cascadia Mono", Menlo, monospace',
} as const;

/** Type scale in rem: a 1.25 ratio from a 1rem (16px) base. */
export const fontSize = {
  xs: '0.75rem',
  sm: '0.875rem',
  md: '1rem',
  lg: '1.25rem',
  xl: '1.5625rem',
  xxl: '1.953rem',
  display: '2.441rem',
} as const;

/** Spacing on a 4px grid, in rem. */
export const space = {
  1: '0.25rem',
  2: '0.5rem',
  3: '0.75rem',
  4: '1rem',
  6: '1.5rem',
  8: '2rem',
  12: '3rem',
} as const;

export const radius = {
  sm: '4px',
  md: '8px',
  lg: '16px',
  pill: '999px',
  circle: '50%',
} as const;

function kebab(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
}

/** Every token as a CSS custom property, e.g. `--color-court: #1C2027`. */
export function cssVariables(): Record<string, string> {
  const vars: Record<string, string> = {};
  for (const [name, value] of Object.entries(palette)) vars[`--color-${kebab(name)}`] = value;
  for (const name of teamColorNames) {
    vars[`--team-${name}`] = teamColors[name].base;
    vars[`--team-${name}-deep`] = teamColors[name].deep;
  }
  for (const [name, value] of Object.entries(fontFamily)) vars[`--font-${name}`] = value;
  for (const [name, value] of Object.entries(fontSize)) vars[`--text-${name}`] = value;
  for (const [name, value] of Object.entries(space)) vars[`--space-${name}`] = value;
  for (const [name, value] of Object.entries(radius)) vars[`--radius-${name}`] = value;
  return vars;
}

/** The custom properties as a `:root { … }` rule. */
export function cssVariablesRule(): string {
  const lines = Object.entries(cssVariables()).map(([name, value]) => `  ${name}: ${value};`);
  return `:root {\n${lines.join('\n')}\n}`;
}
